import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.CCXDMzJr.js";const k=JSON.parse('{"title":"第 1 章 认识 DeepSeek Harness","description":"","frontmatter":{},"headers":[],"relativePath":"ch1-overview.md","filePath":"ch1-overview.md","lastUpdated":null}'),d={name:"ch1-overview.md"};function n(r,e,o,l,h,p){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="第-1-章-认识-deepseek-harness" tabindex="-1">第 1 章 认识 DeepSeek Harness <a class="header-anchor" href="#第-1-章-认识-deepseek-harness" aria-label="Permalink to &quot;第 1 章 认识 DeepSeek Harness&quot;">​</a></h1><h2 id="_1-1-什么是-deepseek-harness" tabindex="-1">1.1 什么是 DeepSeek Harness <a class="header-anchor" href="#_1-1-什么是-deepseek-harness" aria-label="Permalink to &quot;1.1 什么是 DeepSeek Harness&quot;">​</a></h2><p>DeepSeek Harness（命令行工具名为 <code>dsh</code>）是 DeepSeek AI 开发的开源 Agent harness——一个承载、驱动并管理 AI 代理（Agent）的运行时环境。仓库地址为 <a href="https://github.com/deepseek-ai/deepseek-harness" target="_blank" rel="noreferrer">https://github.com/deepseek-ai/deepseek-harness</a>，采用 MIT 许可。</p><p>它不是一个&quot;模型调用封装库&quot;，而是一整套 <strong>Agent 产品运行时</strong>：</p><ul><li>它管理会话（session）的完整生命周期：消息日志、持久化、恢复、分叉（fork）；</li><li>它驱动 Agent 循环：接收输入、组装提示词、调用模型、执行工具、处理流式输出；</li><li>它提供执行能力与安全边界：文件系统、子进程、终端、沙箱、审批策略；</li><li>它自带一个完整的 Web 图形界面（<code>dsh web</code>），同时支持无头（headless）与 ACP（Agent Client Protocol）等运行形态；</li><li>它还提供子代理、目标（goal）、计划（plan）、技能（skill）、上下文压缩等进阶机制。</li></ul><p>而这一切，都建立在同一个插件框架之上：<strong><a href="https://github.com/cordiverse/cordis" target="_blank" rel="noreferrer">Cordis</a></strong>。dsh 官方这样描述自己的架构（<code>README.md</code>）：</p><blockquote><p>It uses an architecture where <strong>everything is a plugin</strong>, and is powered by Cordis.</p></blockquote><p>&quot;一切皆插件&quot;——包括模型适配器、工具注册表、会话日志，甚至 Agent 循环本身（<code>docs/architecture.md</code>）：</p><blockquote><p>Every part of the product is a plugin, including the model adapter, the tool registry, the session log, and the agent loop itself, so every part is replaceable from configuration. There is no privileged core to patch: you extend dsh by mounting a plugin beside the others.</p></blockquote><h2 id="_1-2-核心特性一览" tabindex="-1">1.2 核心特性一览 <a class="header-anchor" href="#_1-2-核心特性一览" aria-label="Permalink to &quot;1.2 核心特性一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>插件化架构</td><td>基于 Cordis：服务（Service）、类型化事件（Event）、可逆副作用（Effect）</td></tr><tr><td>事件溯源会话</td><td>会话是 append-only 的 <code>SessionEvent</code> 日志，模型历史由日志<strong>派生</strong>而非独立存储</td></tr><tr><td>可替换能力接缝</td><td>fs、子进程、沙箱、终端、子代理等均为&quot;定义 + 提供者 + 消费者&quot;三件套</td></tr><tr><td>多运行形态</td><td><code>web</code>（浏览器 GUI）、<code>headless</code>（一次性命令行）、ACP（JSON-RPC stdio）、嵌入式 SDK</td></tr><tr><td>双平面运行时</td><td>Host（Node.js 进程）与 Client（浏览器）各有一套 Cordis 插件树</td></tr><tr><td>配置化组合</td><td>Profile/Bundle/patch 分层，<code>cordis.patch.yml</code> 热更新，无需改代码即可重组产品</td></tr><tr><td>动态插件</td><td>会话内可创建、审批、更新、回滚动态 Cordis 插件，所见即所得地扩展运行时</td></tr><tr><td>内置工具集</td><td>文件系统、Bash、子进程、PTY 终端、后台作业、Web 搜索、技能等</td></tr></tbody></table><h2 id="_1-3-快速上手" tabindex="-1">1.3 快速上手 <a class="header-anchor" href="#_1-3-快速上手" aria-label="Permalink to &quot;1.3 快速上手&quot;">​</a></h2><h3 id="从-npm-运行" tabindex="-1">从 npm 运行 <a class="header-anchor" href="#从-npm-运行" aria-label="Permalink to &quot;从 npm 运行&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @deepseek-ai/dsh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span></span></code></pre></div><p>该命令启动 Web UI，默认服务在 <a href="http://127.0.0.1:3080" target="_blank" rel="noreferrer">http://127.0.0.1:3080</a>。</p><h3 id="从源码运行" tabindex="-1">从源码运行 <a class="header-anchor" href="#从源码运行" aria-label="Permalink to &quot;从源码运行&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/deepseek-ai/deepseek-harness.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deepseek-harness</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dsh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span></span></code></pre></div><h3 id="其他形态" tabindex="-1">其他形态 <a class="header-anchor" href="#其他形态" aria-label="Permalink to &quot;其他形态&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 一次性无头 Agent（需要 DEEPSEEK_API_KEY）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> headless</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;summarize this workspace&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 自指 demo：Agent 可以检查并修改自己正在运行的插件树</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo:cordis</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ACP 自动化服务（JSON-RPC over stdio）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo:acp</span></span></code></pre></div><h2 id="_1-4-版本状态与生态" tabindex="-1">1.4 版本状态与生态 <a class="header-anchor" href="#_1-4-版本状态与生态" aria-label="Permalink to &quot;1.4 版本状态与生态&quot;">​</a></h2><ul><li><strong>开发者预览</strong>：项目处于快速迭代期，官方明确声明存在破坏性变更；</li><li><strong>社区</strong>：GitHub Discussions、Discord 社区；</li><li><strong>插件生态</strong>：官方建议插件仓库添加 <code>dsh-plugin</code> topic 以便被发现；</li><li><strong>上游</strong>：Cordis 框架（vendor 目录内嵌）与 Cosmokit 工具库。</li></ul><h2 id="_1-5-本书的源码地图" tabindex="-1">1.5 本书的源码地图 <a class="header-anchor" href="#_1-5-本书的源码地图" aria-label="Permalink to &quot;1.5 本书的源码地图&quot;">​</a></h2><p>本书所有分析基于仓库根目录 <code>/Users/.../deepseek-harness</code>（写作时 commit <code>47f9438</code>）。后续章节将反复提到以下目录，先建立直觉：</p><table tabindex="0"><thead><tr><th>目录</th><th>内容</th></tr></thead><tbody><tr><td><code>apps/cli</code></td><td><code>dsh</code> 命令行入口（bin、profile-boot、plugin 子命令）</td></tr><tr><td><code>apps/web</code></td><td>Web 前端外壳（Vite + React）</td></tr><tr><td><code>packages/core/*</code></td><td>核心：session、tools、agent、agent-loop、system-prompt、scope</td></tr><tr><td><code>packages/llm/*</code></td><td>LLM 消息词汇与适配器接缝（llm、llm-deepseek、llm-retry 等）</td></tr><tr><td><code>packages/boot/*</code></td><td>启动组装（app-boot、cmdline）与三种 Bundle（base、web-app、headless）</td></tr><tr><td><code>packages/host/*</code></td><td>宿主侧：Web 服务器、静态资源、插件清单</td></tr><tr><td><code>packages/client/*</code></td><td>浏览器侧运行时与全部 UI 组件包</td></tr><tr><td><code>packages/fs</code>、<code>packages/sandbox</code> 等</td><td>各类能力接缝</td></tr><tr><td><code>vendor/cordis</code></td><td>内嵌的 Cordis 框架源码（本书第二部分的主角）</td></tr><tr><td><code>docs/</code></td><td>官方架构、子系统、cookbook 文档（含中文版）</td></tr><tr><td><code>examples/</code></td><td>可运行的示例（web-cordis、headless-agent、mcp-memory、acp-agent 等）</td></tr></tbody></table><p>下一章，我们将展开这张地图。</p>`,25)])])}const g=s(d,[["render",n]]);export{k as __pageData,g as default};
